content.text:
The error came from the scenario, not the surface. The policy callback built its decision as an object literal, and TypeScript widened `'approve'` to `string` before checking it against the halt's decision type. The fix gives the decision an annotation taken from the halt's own decision schema, so the literal stays narrow. I left `H.policy.halt` unchanged because other scenarios call it with this signature.

One concern remains about the surface. Any policy author who returns a literal decision inline will hit the same widening. A builder form that fixes the decision type before the callback, `H.policy.halt(name, halt).decide(fn)`, would remove the problem for everyone. That change would touch every scenario that uses `H.policy.halt`, so it is not made here.

=== FILE: scenarios/11-halts-with-a-clock.ts ===
import { z } from 'zod';
import { H } from 'harness-dsl';
import { anthropic } from 'harness-dsl/anthropic';
import { claudeCode } from 'harness-dsl/claude-code';
import { sqlite } from 'harness-dsl/sqlite';
import { http } from 'harness-dsl/http';
import { supply } from 'harness-dsl/supply';
import { policies } from 'harness-dsl/policies';
import { observers } from 'harness-dsl/observers';

const apiAccount = H.account('anthropic-api', anthropic.api({ apiKey: H.env('ANTHROPIC_API_KEY') }));
const opus = H.model('claude-opus-4-1').pricing(anthropic.pricing());
const apiPool = H.pool('api', [apiAccount]).serves(opus).policy(policies.soonestExpiring());

const category = H.facet('contract-category');

const received = H.state('received').pending();
const drafting = H.state('drafting').active();
const executed = H.state('executed').terminal('success');
const declined = H.state('declined').terminal('failure');
const rejectedByFinance = H.state('rejected-by-finance').terminal('failure');
const failed = H.state('failed').terminal('failure');
const withdrawn = H.state('withdrawn').terminal('neutral');

const contractSchema = z.object({
  contractId: z.string(),
  counterparty: z.string(),
  category: z.string(),
  amountUsd: z.number(),
  redline: z.string(),
});
const contractKind = H.work('Contract').schema(contractSchema).states(received, drafting, executed, declined, rejectedByFinance, failed, withdrawn);

const documentsUrl = H.env('DOCUMENTS_URL');
const documentsToken = H.env('DOCUMENTS_TOKEN');
const documentStore = http.store({
  load: async (unit, ctx) => {
    const response = await fetch(`${ctx.resolve(documentsUrl)}/contracts/${unit.key}`, {
      headers: { authorization: `Bearer ${ctx.resolve(documentsToken)}` },
    });
    return response.ok ? z.object({ data: contractSchema, state: z.string() }).parse(await response.json()) : undefined;
  },
  save: async (unit, change, ctx) => {
    await fetch(`${ctx.resolve(documentsUrl)}/contracts/${unit.key}`, {
      method: 'PUT',
      headers: { authorization: `Bearer ${ctx.resolve(documentsToken)}`, 'content-type': 'application/json' },
      body: JSON.stringify(change),
    });
  },
});

const drafterRole = H.role('contract-drafter').promptFile('prompts/contract-drafter.md').intents(['read']);
const drafter = H.agent('contract-drafter').role(drafterRole).model(opus);
const draftContract = H.skill('draft-contract')
  .input(z.object({ counterparty: z.string(), amountUsd: z.number(), redline: z.string() }))
  .output(z.object({ text: z.string() }))
  .prompt((i) => `Draft the contract with ${i.counterparty} for $${i.amountUsd}. Latest redline:\n${i.redline}`);

const counselDecision = z.object({ verdict: z.enum(['approve', 'return']), notes: z.string() });

const counselReview = H.halt('counsel-review')
  .context(z.object({ contractId: z.string(), category: z.string(), draft: z.string() }))
  .ask((c) => `Review contract ${c.contractId} (${c.category}).`)
  .decision(counselDecision);

const financeSignoff = H.halt('finance-signoff')
  .context(z.object({ contractId: z.string(), amountUsd: z.number() }))
  .ask((c) => `Sign off contract ${c.contractId} for $${c.amountUsd}?`)
  .decision(z.object({ approved: z.boolean(), note: z.string() }));

const executeContract = H.command('execute-contract')
  .input(z.object({ contractId: z.string(), text: z.string() }))
  .effect('unrepeatable')
  .run(async (i, ctx) => {
    const response = await fetch(`${ctx.resolve(documentsUrl)}/contracts/${i.contractId}/execute`, {
      method: 'POST',
      headers: { authorization: `Bearer ${ctx.resolve(documentsToken)}`, 'content-type': 'application/json' },
      body: JSON.stringify({ text: i.text }),
    });
    if (!response.ok) throw new Error(`execution refused: ${response.status}`);
  });

const pageDeputy = H.command('page-finance-deputy')
  .input(z.object({ contractId: z.string(), amountUsd: z.number() }))
  .effect('repeatable')
  .run(async (i, ctx) => {
    await fetch(ctx.resolve(H.env('PAGER_URL')), {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ to: 'finance-deputy', text: `Signoff for ${i.contractId} ($${i.amountUsd}) has waited 20 minutes.` }),
    });
  });

const handleContract = H.flow('contract')
  .input(contractSchema)
  .step('draft', drafter.call(draftContract), (s) => ({
    counterparty: s.input.counterparty,
    amountUsd: s.input.amountUsd,
    redline: s.input.redline,
  }))
  .halt('counsel', counselReview, (s) => ({ contractId: s.input.contractId, category: s.input.category, draft: s.steps.draft.text }))
  .when((s) => s.steps.counsel.verdict === 'return', (f) => f.exit('returnedByCounsel'))
  .halt('signoff', financeSignoff, (s) => ({ contractId: s.input.contractId, amountUsd: s.input.amountUsd }))
  .when((s) => !s.steps.signoff.approved, (f) => f.exit('rejectedByFinance'))
  .step('execute', executeContract, (s) => ({ contractId: s.input.contractId, text: s.steps.draft.text }))
  .exit('executed');

const contractLane = (region: string, tries: number, backoff: 'exponential' | 'none') =>
  H.lane(`contracts-${region}`)
    .of(contractKind)
    .from(
      http.webhook({ path: `/contracts/${region}`, schema: contractSchema, secret: H.env('CONTRACTS_WEBHOOK_SECRET') }).key((d) => d.contractId),
      supply.manual(),
    )
    .store(documentStore)
    .handle(handleContract)
    .exits({
      executed,
      rejectedByFinance,
      returnedByCounsel: { to: received, maxTimes: 1, then: declined },
    })
    .retry({ tries, backoff, delaySeconds: 120, exhausted: failed })
    .wip(3)
    .facet(category, (d) => d.category);

const contractsEu = contractLane('eu', 3, 'exponential');
const contractsUs = contractLane('us', 1, 'none');

const humanCounselApprovals = H.metric('counsel-human-approvals').count(
  H.events.decisions(counselReview, { match: (d) => d.verdict === 'approve', resolver: 'human' }),
);
const counselReturns = H.metric('counsel-returns').count(H.events.decisions(counselReview, { match: (d) => d.verdict === 'return' }));

const provenCategorySkipsCounsel = H.policy.halt('proven-category-skips-counsel', counselReview, ({ context, metrics }) => {
  const where = { facet: { facet: category, value: context.category } };
  const approved = metrics.read(humanCounselApprovals, { where });
  const returned = metrics.read(counselReturns, { where });
  const skip: z.output<typeof counselDecision> = {
    verdict: 'approve',
    notes: `category ${context.category}: ${approved.value ?? 0} approvals over ${approved.samples} samples, no returns`,
  };
  return (approved.value ?? 0) >= 200 && (returned.value ?? 0) === 0 ? skip : undefined;
});

const counselSkip = H.trigger('counsel-skip-for-proven-category')
  .on(counselReview.opened())
  .do(H.ops.resolve(counselReview).by(provenCategorySkipsCounsel));

const signoffDeputyPage = H.trigger('signoff-deputy-page')
  .on(financeSignoff.opened().after('20m'))
  .do(pageDeputy.with((p) => ({ contractId: p.context.contractId, amountUsd: p.context.amountUsd })));

const signoffTimeout = H.trigger('signoff-timeout')
  .on(financeSignoff.opened().after('30m'))
  .do(
    H.ops.resolve(financeSignoff).with((p) => ({
      approved: p.context.amountUsd < 500,
      note: p.context.amountUsd < 500 ? 'approved by timeout under $500' : 'rejected by timeout at $500 or more',
    })),
  );

const counselDecisionSeconds = H.metric('counsel-decision-seconds').median(H.events.decisions(counselReview), 'waitSeconds');
const signoffDecisionSeconds = H.metric('signoff-decision-seconds').median(H.events.decisions(financeSignoff), 'waitSeconds');
const failedAttempts = H.metric('failed-attempts').count(H.events.attempts({ outcome: 'failed' }));
const signoffTimeoutShare = H.metric('signoff-timeout-share').rate(
  H.events.decisions(financeSignoff, { resolver: 'clock' }),
  H.events.decisions(financeSignoff),
);

export const contracts = H.harness('contracts')
  .ledger(sqlite.ledger('.harness/ledger.sqlite'))
  .pools(apiPool)
  .lanes(contractsEu, contractsUs)
  .triggers(counselSkip, signoffDeputyPage, signoffTimeout)
  .scheduler(H.scheduler().policy(H.policy.schedule('oldest-first', ({ candidates }) => [...candidates].sort((a, b) => b.waitingSeconds - a.waitingSeconds))))
  .grants(
    H.grant(http.client('counsel-dashboard', { port: 8443, token: H.env('COUNSEL_TOKEN') }), H.ops.resolve(counselReview)),
    H.grant(claudeCode.client('finance', { session: 'finance' }), H.ops.resolve(financeSignoff)),
    H.grant(claudeCode.client('finance-deputy', { session: 'finance-deputy' }), H.ops.resolve(financeSignoff)),
    H.grant(http.client('auditor', { port: 8444, token: H.env('AUDITOR_TOKEN') }), H.ops.work.read, H.ops.telemetry.read),
    H.grant(http.client('operator', { port: 8445, token: H.env('OPERATOR_TOKEN') }), H.ops.work.read, H.ops.work.write),
  )
  .metrics(counselDecisionSeconds, signoffDecisionSeconds, failedAttempts, signoffTimeoutShare)
  .observe(observers.board({ path: '.harness/board.md' }), observers.telemetry({ path: '.harness/telemetry.md' }));

=== END ===

The two errors share one cause. `NoInfer<D>`, used as the contextual return type, does not keep string literals. So `'approved'` and `'approve'` widened to `string` inside the `decide` callbacks of `H.policy.halt` and `Flow.halt`.

The fix is in the surface, not the scenario:

- **Halt typed by identity.** Both `H.policy.halt` and `Flow.halt` now take the halt as a generic `Hl extends Halt<string, unknown>`. That type is inferred from the halt argument alone.
- **Callback types derived from the halt.** The decision type inside the callbacks comes from a new `DecisionOf<Hl>`, so it is fixed by the halt entity before any callback is checked. The callbacks get the halt's real decision union as their contextual type, and literals are kept.
- **No loss of strictness.** The callbacks cannot widen or change the decision type.
- **Unchanged.** The second `Flow.halt` overload (an inline decision schema) produced no error and keeps its signature.
- **No scenario edits.** The scenarios are unchanged.

=== FILE: h.d.ts ===
declare module 'harness-dsl' {
  import { z } from 'zod';
  import {
    Named,
    EnvRef,
    PortRef,
    Verdict,
    State,
    UnitView,
    WorkRef,
    Metrics,
    Policy,
    AccountState,
    Account,
    Model,
    RunnerBackend,
    Workspace,
    Supplier,
    Store,
    MemoryStore,
    Ledger,
    Client,
    Observer,
    Scope,
    MetricRef,
    Measure,
    Window,
    JobPoll,
    LeaseMode,
    DecisionSource,
  } from 'harness-dsl/kernel';
  export * from 'harness-dsl/kernel';

  export type Schema<T> = z.ZodType<T>;
  export type Empty = { readonly [K in never]: never };

  export interface KindShape<A, S extends State> extends WorkRef<S['name']> {
    readonly entity: 'kind';
    readonly _types?: { readonly attrs: A; readonly states: S };
  }

  export interface Kind<N extends string, A, S extends State> extends KindShape<A, S> {
    readonly name: N;
    attributes<A2 extends object>(schema: Schema<A2>): Kind<N, A2, S>;
    states<S2 extends State[]>(...states: S2): Kind<N, A, S2[number]>;
    key(identity: (attrs: A) => string): Kind<N, A, S>;
    initial(state: S): Kind<N, A, S>;
    onAttemptFailed(state: S): Kind<N, A, S>;
    onCancelled(state: S): Kind<N, A, S>;
  }

  export interface Signal<N extends string = string, P = unknown> extends Named {
    readonly name: N;
    readonly _payload?: P;
    payload<P2>(schema: Schema<P2>): Signal<N, P2>;
  }

  export interface Halt<N extends string = string, D = unknown> extends Named {
    readonly entity: 'halt';
    readonly name: N;
    readonly _decision?: D;
  }

  export type DecisionOf<Hl> = Hl extends Halt<string, infer D> ? D : never;

  export interface Resource extends Named {
    readonly entity: 'resource';
  }

  export interface Lease {
    readonly resource: Resource;
    readonly mode: LeaseMode;
  }

  export interface Executable<I, O> extends Named {
    readonly _io?: { readonly in: (input: I) => void; readonly out: O };
  }

  export interface Job<I, O> extends Executable<I, O> {
    readonly entity: 'job';
  }

  export interface CommandResult {
    readonly exitCode: number;
    readonly stdout: string;
    readonly stderr: string;
  }

  export interface Command<I, O> extends Executable<I, O> {
    input<I2>(schema: Schema<I2>): Command<I2, O>;
    argv(argv: readonly string[] | ((input: I) => readonly string[])): Command<I, O>;
    output<O2>(schema: Schema<O2>): Command<I, O2>;
    runner(runner: Runner | ((input: I) => Runner)): Command<I, O>;
    acceptExitCodes(...exitCodes: number[]): Command<I, O>;
  }

  export interface Runner extends Named {
    readonly backend: RunnerBackend;
    slots(count: number): Runner;
    preflight(check: Executable<void, unknown>): Runner;
  }

  export type Intent = 'read' | 'edit' | 'run' | 'search' | 'browse' | 'halt' | 'record';

  export interface Role extends Named {
    intents(...intents: Intent[]): Role;
    instructions(text: string): Role;
  }

  export interface AgentTask {
    readonly task: string;
    readonly resources?: readonly string[];
    readonly skills?: readonly string[];
  }

  export interface Guard { readonly guard: 'lease' | 'beforeStop' }

  export interface Agent<O> extends Executable<AgentTask, O> {
    role(role: Role): Agent<O>;
    model(model: Model | ModelPolicy): Agent<O>;
    pool(pool: Pool): Agent<O>;
    output<O2>(schema: Schema<O2>): Agent<O2>;
    workspace(workspace: Workspace): Agent<O>;
    guards(...guards: Guard[]): Agent<O>;
    batch(): Executable<readonly AgentTask[], readonly O[]>;
  }

  export interface PolicyCtx {
    readonly kind: WorkRef;
    readonly metrics: Metrics;
  }

  export interface ModelPolicy extends Policy<PolicyCtx, Model> {
    readonly candidates: readonly Model[];
  }

  export interface HaltPolicyCtx<A> {
    readonly unit: UnitView<A>;
    readonly metrics: Metrics;
  }

  export interface HaltPolicy<A, D> extends Policy<HaltPolicyCtx<A>, D | undefined> {
    readonly entity: 'haltPolicy';
    readonly halt: Halt<string, D>;
  }

  export interface AccountPolicyCtx {
    readonly candidates: readonly AccountState[];
    readonly now: Date;
  }

  export type AccountPolicy = Policy<AccountPolicyCtx, AccountState | undefined>;

  export interface Pool extends Named {
    accounts(...accounts: Account[]): Pool;
    share(account: Account, fraction: number): Pool;
    drain(policy: AccountPolicy): Pool;
    fallback(account: Account): Pool;
  }

  export interface MemoryKind extends Named {
    readonly trust: 'experience' | 'taste';
  }

  export interface Journal extends Named {
    readonly entity: 'journal';
    store(store: MemoryStore): Journal;
    recall(recall: { readonly by: 'specificity' | 'similarity'; readonly limit: number }): Journal;
    readBy(...roles: Role[]): Journal;
    recordedBy(...roles: Role[]): Journal;
  }

  export interface MemoryDraft {
    readonly text: string;
    readonly when?: Scope;
    readonly status?: 'candidate' | 'active';
  }

  export interface Retry {
    readonly maxAttempts: number;
    readonly backoff: 'fixed' | 'exponential';
    readonly initialDelayMs: number;
  }

  export interface StepOptions<I> {
    readonly retry?: Retry;
    readonly afterCrash?: 'rerun' | 'park' | 'askDriver';
    readonly alreadyDone?: Executable<I, boolean>;
  }

  export interface FlowCtx<In, P, St> {
    readonly unit: UnitView<In>;
    readonly params: P;
    readonly steps: St;
    readonly metrics: Metrics;
    readonly iteration: number;
    readonly now: Date;
  }

  export interface HaltOptions<In, P, St, D> {
    readonly ask: (ctx: FlowCtx<In, P, St>) => string;
    readonly skip?: HaltPolicy<In, D> | ((ctx: FlowCtx<In, P, St>) => D | undefined);
    readonly clock?: {
      readonly afterMinutes: number;
      readonly decide: (ctx: FlowCtx<In, P, St>) => D;
    };
  }

  export interface ChildResult {
    readonly unitId: string;
    readonly state: string;
    readonly verdict: Verdict;
  }

  export interface Flow<In, P, St, X extends string, N extends string> extends Named {
    readonly _types?: {
      readonly input: (attrs: In) => void;
      readonly params: (params: P) => P;
      readonly steps: St;
      readonly exits: X;
      readonly stepNames: N;
    };
    input<In2>(schema: Schema<In2>): Flow<In2, P, St, X, N>;
    params<P2>(schema: Schema<P2>): Flow<In, P2, St, X, N>;
    step<M extends string, O>(
      name: M,
      exec: Executable<void, O>,
      options?: StepOptions<void>,
    ): Flow<In, P, St & { readonly [K in M]: O }, X, N | M>;
    step<M extends string, I, O>(
      name: M,
      exec: Executable<I, O>,
      input: (ctx: FlowCtx<In, P, St>) => I,
      options?: StepOptions<I>,
    ): Flow<In, P, St & { readonly [K in M]: O }, X, N | M>;
    halt<M extends string, Hl extends Halt<string, unknown>>(
      name: M,
      halt: Hl,
      options: HaltOptions<In, P, St, DecisionOf<Hl>>,
    ): Flow<In, P, St & { readonly [K in M]: DecisionOf<Hl> }, X, N | M>;
    halt<M extends string, D>(
      name: M,
      halt: {
        readonly ask: (ctx: FlowCtx<In, P, St>) => string;
        readonly decision: Schema<D>;
        readonly skip?: (ctx: FlowCtx<In, P, St>) => NoInfer<D> | undefined;
      },
    ): Flow<In, P, St & { readonly [K in M]: D }, X, N | M>;
    wait<M extends string>(
      name: M,
      wait: { readonly ms: number },
    ): Flow<In, P, St & { readonly [K in M]: Date }, X, N | M>;
    spawn<M extends string, A2>(
      name: M,
      lane: LaneShape<A2, State, unknown>,
      children: (ctx: FlowCtx<In, P, St>) => readonly A2[],
    ): Flow<In, P, St & { readonly [K in M]: readonly ChildResult[] }, X, N | M>;
    loop<M extends string, St2, X2 extends string, N2 extends string>(
      name: M,
      body: (flow: Flow<In, P, St, X, N>) => Flow<In, P, St2, X2, N2>,
      bounds: {
        readonly max?: number | ((ctx: FlowCtx<In, P, St>) => number);
        readonly counts?: (ctx: FlowCtx<In, P, St2>) => boolean;
        readonly until?: (ctx: FlowCtx<In, P, St2>) => boolean;
      },
    ): Flow<In, P, St2, X2, N2 | M>;
    exit<M extends string>(
      name: M,
      when?: (ctx: FlowCtx<In, P, St>) => boolean,
    ): Flow<In, P, St, X | M, N>;
  }

  export interface LaneShape<A, S extends State, St> extends WorkRef<S['name']> {
    readonly entity: 'lane';
    readonly _types?: { readonly attrs: A; readonly states: S; readonly steps: St };
  }

  export type LaneRef = LaneShape<unknown, State, unknown>;

  export type ActiveState<S extends State> = Extract<S, State<string, 'active'>>;
  export type WaitingState<S extends State> = Extract<S, State<string, 'waiting'>>;

  export interface HandlerMap<S extends State, X extends string, N extends string> {
    readonly exits: { readonly [K in X]: S };
    readonly during?: { readonly [K in N]?: ActiveState<S> };
  }

  export type InputFits<A, I> = [A] extends [I] ? unknown : { readonly flowInputDoesNotFitKind: I };

  export interface Reaction<A, S extends State, N extends string, P, St> {
    readonly update?: (attrs: A, payload: P) => A;
    readonly restart?: N;
    readonly enter?: S;
    readonly resolve?: { readonly [K in keyof St & N]?: (payload: P, attrs: A) => St[K] };
  }

  export interface Route { readonly route: 'create' | 'signal' | 'skip' }

  export interface Router<A, SN extends string> {
    create(attrs: A): Route;
    signal<P>(
      signal: Signal<string, P>,
      target: string | ((unit: UnitView<A, SN>) => boolean),
      payload: P,
    ): Route;
    skip(): Route;
  }

  export interface OperatorSupplier extends Named { readonly operator: true }

  export interface Lane<A, S extends State, St, N extends string> extends LaneShape<A, S, St> {
    readonly _types?: { readonly attrs: A; readonly states: S; readonly steps: St; readonly stepNames: N };
    supply(supplier: OperatorSupplier): Lane<A, S, St, N>;
    supply<E>(
      supplier: Supplier<E>,
      route: (event: E, to: Router<A, S['name']>) => Route | readonly Route[],
    ): Lane<A, S, St, N>;
    store(store: Store): Lane<A, S, St, N>;
    handler<I, St2, X extends string, N2 extends string>(
      flow: Flow<I, void, St2, X, N2>,
      map: HandlerMap<S, X, N2> & InputFits<A, I>,
    ): Lane<A, S, St2, N2>;
    handler<I, P, St2, X extends string, N2 extends string>(
      flow: Flow<I, P, St2, X, N2>,
      map: HandlerMap<S, X, N2> & { readonly params: P } & InputFits<A, I>,
    ): Lane<A, S, St2, N2>;
    retry(policy: Retry & { readonly exhausted: S }): Lane<A, S, St, N>;
    lease(claim: (unit: UnitView<A, S['name']>) => Lease): Lane<A, S, St, N>;
    order(
      sequence: (unit: UnitView<A, S['name']>) => string,
      options: { readonly onEarlierFailed: WaitingState<S> },
    ): Lane<A, S, St, N>;
    on<P>(signal: Signal<string, P>, reaction: Reaction<A, S, N, P, St>): Lane<A, S, St, N>;
    ceiling(ceiling: { readonly maxUsd: number; readonly onExceed: 'halt' | 'fail' }): Lane<A, S, St, N>;
  }

  export interface Tick { readonly at: Date }
  export type Weekday = 'mon' | 'tue' | 'wed' | 'thu' | 'fri' | 'sat' | 'sun';

  export interface Clock extends Supplier<Tick> {
    every(interval: { readonly minutes: number }): Clock;
    at(time: string, options?: { readonly on?: Weekday | number; readonly tz?: string }): Clock;
  }

  export interface TransitionEvent<A, SN extends string = string> {
    readonly unit: UnitView<A, SN>;
    readonly to: SN;
    readonly attempt?: { readonly durationMs: number };
    readonly at: Date;
  }

  export interface PatternEvent<A, SN extends string = string> extends TransitionEvent<A, SN> {
    readonly group: string;
    readonly streak: number;
  }

  export interface TimerEvent<A, SN extends string = string> {
    readonly unit: UnitView<A, SN>;
    readonly at: Date;
  }

  export interface StepEvent<A, O, St> {
    readonly unit: UnitView<A>;
    readonly ok: boolean;
    readonly output?: O;
    readonly outputs: { readonly [K in keyof St]?: St[K] };
    readonly models: { readonly [K in keyof St]?: string };
    readonly durationMs: number;
    readonly at: Date;
  }

  export interface InvocationEvent {
    readonly model?: string;
    readonly ok: boolean;
    readonly costUsd: number;
  }

  export interface HaltedEvent<A> {
    readonly unit: UnitView<A>;
    readonly halt: string;
    readonly ask: string;
    readonly haltedAt: Date;
    readonly at: Date;
  }

  export interface DecisionEvent<A, D> {
    readonly unit: UnitView<A>;
    readonly decision: D;
    readonly resolvedBy: DecisionSource;
    readonly client?: string;
    readonly waitedMs: number;
    readonly at: Date;
  }

  export interface LeaseEvent {
    readonly unit: UnitView<unknown>;
    readonly resource: Resource;
    readonly mode: LeaseMode;
    readonly waitedMs: number;
    readonly at: Date;
  }

  export type Threshold = { readonly below: number } | { readonly above: number };

